const users = [
  { id: 1, name: 'Alice', age: 30, role: 'admin' },
  { id: 2, name: 'Bob', age: 25, role: 'user' },
  { id: 3, name: 'Charlie', age: 35, role: 'user' },
  { id: 4, name: 'Diana', age: 28, role: 'admin' },
];

// --- Searching ---
const found = users.find(u => u.name === 'Bob');          // { id: 2, ... }
const index = users.findIndex(u => u.age > 30);           // 2
const exists = users.some(u => u.role === 'admin');        // true
const allAdults = users.every(u => u.age >= 18);           // true

// --- Filtering & Mapping ---
const admins = users.filter(u => u.role === 'admin');      // [Alice, Diana]
const names = users.map(u => u.name);                      // ['Alice', ...]
const flatNames = [['a', 'b'], ['c']].flat();             // ['a','b','c']
const mapped = users.flatMap(u => [u.name, u.role]);       // flat version

// --- Reducing ---
const totalAge = users.reduce((sum, u) => sum + u.age, 0); // 118
const grouped = users.reduce((acc, u) => {
  (acc[u.role] = acc[u.role] || []).push(u);
  return acc;
}, {});  // { admin: [...], user: [...] }

// --- Sorting ---
const byAge = [...users].sort((a, b) => a.age - b.age);
const byName = [...users].sort((a, b) => a.name.localeCompare(b.name));

// --- Other useful methods ---
const unique = [...new Set([1, 2, 2, 3, 3])];              // [1, 2, 3]
const chunked = Array.from({ length: 3 }, (_, i) =>
  users.slice(i * 2, (i + 1) * 2)
); // Chunk into pairs

console.log({ found, admins, totalAge, grouped, unique });

import { useState, useEffect, useCallback } from 'react';

/**
 * useLocalStorage — Persist state in localStorage with type safety.
 *
 * Automatically syncs across tabs via the 'storage' event.
 *
 * @param key - localStorage key
 * @param initialValue - Default value if key doesn't exist
 *
 * @example
 * const [theme, setTheme] = useLocalStorage('theme', 'dark');
 * const [cart, setCart] = useLocalStorage<CartItem[]>('cart', []);
 */
export function useLocalStorage<T>(key: string, initialValue: T) {
  const [storedValue, setStoredValue] = useState<T>(() => {
    try {
      const item = window.localStorage.getItem(key);
      return item ? (JSON.parse(item) as T) : initialValue;
    } catch {
      console.warn(`Error reading localStorage key "${key}"`);
      return initialValue;
    }
  });

  const setValue = useCallback(
    (value: T | ((val: T) => T)) => {
      try {
        const valueToStore =
          value instanceof Function ? value(storedValue) : value;
        setStoredValue(valueToStore);
        window.localStorage.setItem(key, JSON.stringify(valueToStore));
      } catch (error) {
        console.warn(`Error setting localStorage key "${key}":`, error);
      }
    },
    [key, storedValue]
  );

  // Sync across tabs
  useEffect(() => {
    const handleStorageChange = (e: StorageEvent) => {
      if (e.key === key && e.newValue !== null) {
        setStoredValue(JSON.parse(e.newValue));
      }
    };
    window.addEventListener('storage', handleStorageChange);
    return () => window.removeEventListener('storage', handleStorageChange);
  }, [key]);

  return [storedValue, setValue] as const;
}

/**
 * JWT Authentication Middleware for Express.js
 *
 * Features:
 * - Token extraction from Authorization header or cookies
 * - Token verification with expiry check
 * - Role-based access control helper
 * - Refresh token support
 */

const jwt = require('jsonwebtoken');

const JWT_SECRET = process.env.JWT_SECRET || 'your-secret-key';
const JWT_EXPIRES_IN = process.env.JWT_EXPIRES_IN || '1d';

// Generate tokens
function generateToken(payload) {
  return jwt.sign(payload, JWT_SECRET, { expiresIn: JWT_EXPIRES_IN });
}

function generateRefreshToken(payload) {
  return jwt.sign(payload, JWT_SECRET, { expiresIn: '7d' });
}

// Auth middleware
function authenticate(req, res, next) {
  const token =
    req.cookies?.token ||
    req.headers.authorization?.replace('Bearer ', '');

  if (!token) {
    return res.status(401).json({ error: 'Authentication required' });
  }

  try {
    const decoded = jwt.verify(token, JWT_SECRET);
    req.user = decoded;
    next();
  } catch (err) {
    if (err.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    return res.status(403).json({ error: 'Invalid token' });
  }
}

// Role-based access control
function authorize(...roles) {
  return (req, res, next) => {
    if (!req.user || !roles.includes(req.user.role)) {
      return res.status(403).json({ error: 'Insufficient permissions' });
    }
    next();
  };
}

module.exports = {
  generateToken,
  generateRefreshToken,
  authenticate,
  authorize,
};

/**
 * TypeScript Utility Types — Practical Guide
 * Common type patterns for real-world applications.
 */

// --- 1. Make specific fields optional ---
type PartialBy<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;

interface User {
  id: number;
  name: string;
  email: string;
  avatar: string;
}

type CreateUser = PartialBy<User, 'id' | 'avatar'>;
// { name: string; email: string; id?: number; avatar?: string }

// --- 2. Deep Partial (all nested fields optional) ---
type DeepPartial<T> = {
  [P in keyof T]?: T[P] extends object ? DeepPartial<T[P]> : T[P];
};

interface Config {
  db: { host: string; port: number; ssl: boolean };
  cache: { ttl: number; strategy: string };
}

type PartialConfig = DeepPartial<Config>;
// Can pass { db: { port: 5433 } } without other fields

// --- 3. Extract function return type ---
async function fetchUser(id: number): Promise<User> {
  return { id, name: 'Alice', email: 'alice@example.com', avatar: '' };
}

type FetchUserReturn = Awaited<ReturnType<typeof fetchUser>>; // User

// --- 4. Discriminated Unions ---
type Result<T, E = Error> =
  | { success: true; data: T }
  | { success: false; error: E };

function handleResult(result: Result<User>) {
  if (result.success) {
    console.log(result.data.name); // TypeScript knows data exists
  } else {
    console.error(result.error);   // TypeScript knows error exists
  }
}

// --- 5. Builder Pattern with Types ---
type Builder<T> = {
  [K in keyof T]-?: (value: T[K]) => Builder<T>;
} & { build: () => T };

export type { PartialBy, DeepPartial, Result, Builder };
